int usb_probe_and_configure(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct device_config *host_config, *device_config;
    int ret;

    host_config = kzalloc(sizeof(*host_config), GFP_KERNEL);
    if (!host_config)
        return -ENOMEM;

    device_config = kzalloc(sizeof(*device_config), GFP_KERNEL);
    if (!device_config) {
        kfree(host_config);
        return -ENOMEM;
    }

    ret = usb_control_msg(
        interface_to_usbdev(intf),
        usb_rcvctrlpipe(interface_to_usbdev(intf), 0),
        USB_SET_HOST_FORMAT, USB_DIR_OUT | USB_TYPE_CLASS | USB_RECIP_INTERFACE,
        0, 0, host_config, sizeof(*host_config), USB_CTRL_MSG_TIMEOUT);
    if (ret < 0) {
        kfree(host_config);
        kfree(device_config);
        return ret;
    }

    ret = usb_control_msg(
        interface_to_usbdev(intf),
        usb_rcvctrlpipe(interface_to_usbdev(intf), 0),
        USB_GET_DEVICE_CONFIG, USB_DIR_IN | USB_TYPE_CLASS | USB_RECIP_INTERFACE,
        0, 0, device_config, sizeof(*device_config), USB_CTRL_MSG_TIMEOUT);
    if (ret < 0) {
        kfree(host_config);
        kfree(device_config);
        return ret;
    }

    if (device_config->num_interfaces == 0) {
        kfree(host_config);
        kfree(device_config);
        return -ENODEV;
    }

    intf->needs_remote_wakeup = 1;
    usb_set_intfdata(intf, host_config);

    for (int i = 0; i < device_config->num_interfaces; i++) {
        struct can_device *can_dev;

        can_dev = can_dev_alloc();
        if (!can_dev) {
            kfree(host_config);
            kfree(device_config);
            return -ENOMEM;
        }

        ret = can_dev_init(can_dev, intf);
        if (ret < 0) {
            can_dev_free(can_dev);
            kfree(host_config);
            kfree(device_config);
            return ret;
        }

        ret = can_dev_register(can_dev);
        if (ret < 0) {
            can_dev_free(can_dev);
            kfree(host_config);
            kfree(device_config);
            return ret;
        }
    }

    return 0;
}

int usb_init(struct usb_interface *intf, const struct usb_device_id *id) {
    struct host_config *host_cfg;
    struct dev_config *dev_cfg;
    int ret = 0;
    int i;

    host_cfg = kzalloc(sizeof(*host_cfg), GFP_KERNEL);
    if (!host_cfg)
        return -ENOMEM;

    dev_cfg = kzalloc(sizeof(*dev_cfg), GFP_KERNEL);
    if (!dev_cfg) {
        kfree(host_cfg);
        return -ENOMEM;
    }

    ret = usb_control_msg(intf->cur_altsetting->desc.bInterfaceNumber,
                          USB_DIR_OUT | USB_TYPE_CLASS | USB_RECIP_INTERFACE,
                          USB_REQ_SET_INTERFACE, 0, 0, NULL, 0, 5000);
    if (ret < 0) {
        kfree(host_cfg);
        kfree(dev_cfg);
        return ret;
    }

    ret = usb_get_device_descriptor(intf->dev, dev_cfg);
    if (ret < 0) {
        kfree(host_cfg);
        kfree(dev_cfg);
        return ret;
    }

    for (i = 0; i < dev_cfg->num_interfaces; i++) {
        struct can_device *can_dev;

        can_dev = create_can_device(&intf->dev->dev, i);
        if (IS_ERR(can_dev)) {
            ret = PTR_ERR(can_dev);
            while (--i >= 0) {
                struct can_device *tmp = get_can_device(i);
                if (tmp)
                    destroy_can_device(tmp);
            }
            kfree(host_cfg);
            kfree(dev_cfg);
            return ret;
        }
    }

    intf->drv_priv = host_cfg;
    return 0;
}

int usb_probe_configure(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct usb_device *udev = interface_to_usbdev(intf);
    struct device *dev = &intf->dev;
    int ret = 0;
    void *host_config = NULL;
    void *device_config = NULL;

    host_config = kmalloc(sizeof(struct host_config), GFP_KERNEL);
    if (!host_config) {
        ret = -ENOMEM;
        goto error;
    }

    device_config = kmalloc(sizeof(struct device_config), GFP_KERNEL);
    if (!device_config) {
        ret = -ENOMEM;
        goto error;
    }

    ret = usb_control_msg(udev, usb_sndctrlpipe(udev, 0),
                          USB_REQ_SET_CONFIGURATION, USB_DIR_OUT |
                          USB_TYPE_STANDARD | USB_RECIP_DEVICE,
                          1, 0, NULL, 0, USB_CTRL_MSG_TIMEOUT);
    if (ret < 0)
        goto error;

    ret = usb_get_device_descriptor(udev, sizeof(*device_config));
    if (ret < 0)
        goto error;

    if (device_config->num_interfaces != 1) {
        ret = -EINVAL;
        goto error;
    }

    struct can_device *can_dev = alloc_can_dev();
    if (!can_dev) {
        ret = -ENOMEM;
        goto error;
    }

    ret = register_can_device(can_dev);
    if (ret < 0)
        goto error;

    dev_set_drvdata(dev, can_dev);

    return 0;

error:
    kfree(host_config);
    kfree(device_config);
    return ret;
}

int usb_probe_and_configure(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct usb_device *udev = interface_to_usbdev(intf);
    struct host_config *host_cfg;
    struct dev_config *dev_cfg;
    int ret = 0;
    int i;

    host_cfg = kzalloc(sizeof(*host_cfg), GFP_KERNEL);
    if (!host_cfg)
        return -ENOMEM;

    dev_cfg = kzalloc(sizeof(*dev_cfg), GFP_KERNEL);
    if (!dev_cfg) {
        ret = -ENOMEM;
        goto free_host_cfg;
    }

    ret = usb_control_msg(udev, usb_sndctrlpipe(udev, 0),
                          USB_REQ_SET_CONFIGURATION,
                          USB_TYPE_CLASS | USB_RECIP_INTERFACE,
                          0x01, 0x00, NULL, 0, USB_CTRL_MSG_TIMEOUT);
    if (ret < 0)
        goto free_dev_cfg;

    ret = usb_get_device_descriptor(udev, sizeof(udev->descriptor));
    if (ret < 0)
        goto free_dev_cfg;

    dev_cfg->num_interfaces = udev->descriptor.bNumInterfaces;
    dev_cfg->interfaces = kcalloc(dev_cfg->num_interfaces,
                                  sizeof(*dev_cfg->interfaces),
                                  GFP_KERNEL);
    if (!dev_cfg->interfaces) {
        ret = -ENOMEM;
        goto free_dev_cfg;
    }

    for (i = 0; i < dev_cfg->num_interfaces; i++) {
        dev_cfg->interfaces[i] = kzalloc(sizeof(**dev_cfg->interfaces), GFP_KERNEL);
        if (!dev_cfg->interfaces[i]) {
            ret = -ENOMEM;
            goto free_interfaces;
        }

        ret = init_can_device(dev_cfg->interfaces[i]);
        if (ret < 0)
            goto free_interfaces;
    }

    intf->drv_data = dev_cfg;
    return 0;

free_interfaces:
    for (i = 0; i < dev_cfg->num_interfaces; i++)
        kfree(dev_cfg->interfaces[i]);
    kfree(dev_cfg->interfaces);
free_dev_cfg:
    kfree(dev_cfg);
free_host_cfg:
    kfree(host_cfg);
    return ret;
}
